import pytest
from hypothesis import given, strategies as st

from ledger.accounts.signup import check_if_new_user_signup_allowed

LABELS = st.from_regex(r"[a-z][a-z0-9]{0,9}", fullmatch=True)


@pytest.mark.invariant("signup_rejects_existing_domain")
@given(local=LABELS, subdomain=LABELS)
def test_any_subdomain_of_a_customer_is_refused(local, subdomain):
    email = f"{local}@{subdomain}.acme.com"
    assert check_if_new_user_signup_allowed(email, {"acme.com"}) is False
